begin;

update public.spell_catalog set name_ru='Ответный удар', effect_summary='Реакцией на получаемый урон уменьшаешь его на 4к6 + модификатор заклинательной характеристики. Если источник урона — существо в пределах 60 футов, оно делает спасбросок Телосложения и получает 4к6 урона силовым полем при провале или половину при успехе.', author_description='Защита и ответка в одном движении: сначала пережить удар, потом вернуть часть проблемы отправителю.', author_comment='Очень вежливая магия: всё полученное старается вернуть.', upcast='И снижение урона, и ответный урон увеличиваются на 1к6 за каждый уровень ячейки выше 4.', notes='Реакция используется именно в ответ на получение урона. Ответный урон возможен только если источник — существо в пределах дистанции.', casting_time='1 реакция, когда ты получаешь урон' where slug='backlash' and source_kind='official';

update public.spell_catalog set name_ru='Волна погибели', effect_summary='Создаёшь сферу чернильного магического тумана радиусом 20 футов на срок до 1 минуты с концентрацией. Существа, оказавшиеся в сфере, делают спасбросок Мудрости: при провале получают 5к6 психического урона и вычитают 1к6 из спасбросков до конца следующего хода; при успехе получают половину урона. Сфера в начале каждого твоего хода движется на 10 футов от тебя.', author_description='Тёмная сфера не просто закрывает обзор, а медленно плывёт по полю, ломая спасброски и давя психику всем, кого догонит.', author_comment='Облако, которое не стоит на месте и явно знает, куда тебе не хочется идти.', upcast='Обычное усиление ячейкой не меняет базовые параметры.', notes='Туман создаёт магическую Тьму и рассеивается сильным ветром. Существо делает спасбросок не более одного раза за ход. У заклинания есть отдельный вариант кругового сотворения.', casting_time='1 действие' where slug='doomtide' and source_kind='official';

update public.spell_catalog set name_ru='Стихийная погибель', effect_summary='Выбираешь кислоту, холод, огонь, электричество или звук. Цель делает спасбросок Телосложения. При провале до 1 минуты с концентрацией она теряет сопротивление выбранному типу, а первый раз за ход, когда получает урон этого типа, получает дополнительно 2к6.', author_description='Ты не создаёшь стихию — ты делаешь так, чтобы конкретная стихия внезапно стала для цели значительно опаснее.', author_comment='Лучший друг группы, которая уже договорилась, чем именно сегодня жечь босса.', upcast='За каждый уровень ячейки выше 4 можно выбрать ещё одну цель; все цели должны находиться не далее 30 футов друг от друга.', notes='Иммунитет не снимается. Дополнительные 2к6 срабатывают не чаще одного раза за ход.', casting_time='1 действие' where slug='elemental-bane' and source_kind='official';

update public.spell_catalog set name_ru='Поиск высшего скакуна', effect_summary='Призываешь верного духа-скакуна в форме грифона, пегаса, перитона, лютого волка, носорога или саблезубого тигра. Выбираешь его природу — небожитель, фея или исчадие. Он разумнее обычного зверя, понимает один твой язык, связан с тобой телепатически и служит постоянным скакуном, пока не погибнет или не будет отпущен.', author_description='Это уже не просто лошадь. Это магический транспорт, боевой партнёр и иногда летающий способ полностью изменить геометрию приключения.', author_comment='После пегаса обычная конюшня начинает ощущаться как компромисс.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Пока ты верхом на скакуне, заклинание, которое нацелено только на тебя, может также затронуть его. Повторное сотворение заменяет предыдущего скакуна.', casting_time='10 минут' where slug='find-greater-steed' and source_kind='official';

update public.spell_catalog set name_ru='Скорый курьер Гальдера', effect_summary='Призываешь неуязвимого малого воздушного элементаля с пустым сундуком 3×3×3 фута. Кладёшь внутрь предметы, называешь известное тебе живое существо, закрываешь крышку — и сундук мгновенно переносится к адресату. Только адресат может забрать содержимое; непринятые вещи возвращаются к твоим ногам по окончании заклинания.', author_description='Междугородняя доставка без дорог, лошадей и курьеров, которые требуют объяснить, почему в сундуке человеческий череп.', author_comment='Самая дорогая экспресс-доставка, зато слово «экспресс» здесь буквально магическое.', upcast='Ячейкой 8 уровня сундук можно отправить существу на другом плане существования.', notes='Материальный компонент стоимостью 25 зм расходуется. Если цель недоступна магическому обнаружению или находится на другом плане без усиления, содержимое возвращается к тебе.', casting_time='1 действие' where slug='galder-s-speedy-courier' and source_kind='official';

update public.spell_catalog set name_ru='Печать врат', effect_summary='Укрепляешь ткань планов в неподвижном кубе 30 футов на 24 часа. Все порталы внутри закрываются и не могут открыться; заклинания и эффекты планарного перемещения не могут войти в область или выйти из неё.', author_description='Магическая табличка «проход закрыт», только для дверей между мирами.', author_comment='В Сигиле закрыть дверь — иногда куда серьёзнее, чем построить стену.', upcast='Ячейкой 6 уровня или выше эффект длится, пока не будет рассеян.', notes='Материальный компонент — сломанный ключ портала, который расходуется. Область неподвижна.', casting_time='1 минута' where slug='gate-seal' and source_kind='official';

update public.spell_catalog set name_ru='Гравитационная воронка', effect_summary='Создаёшь в точке в пределах 120 футов сферу искажённой гравитации радиусом 20 футов. Существа в ней делают спасбросок Телосложения: при провале получают 5к10 силового урона и притягиваются на 20 футов к центру; при успехе получают половину урона без перемещения.', author_description='На секунду центр комнаты становится гораздо более убедительным направлением, чем все остальные.', author_comment='Гравитация обычно притягивает вниз. Эта просто решила сменить адрес.', upcast='Урон увеличивается на 1к10 за каждый уровень ячейки выше 4.', notes='Незакреплённые предметы в области также притягиваются к центру.', casting_time='1 действие' where slug='gravity-sinkhole' and source_kind='official';

update public.spell_catalog set name_ru='Страж природы', effect_summary='Бонусным действием принимаешь один из двух природных аспектов на срок до 1 минуты с концентрацией. Первобытный зверь даёт +10 футов скорости, тёмное зрение 120 футов, преимущество на атаки Силой и +1к6 силового урона рукопашным оружием. Великое древо даёт 10 временных хитов, преимущество на спасброски Телосложения и атаки Ловкостью/Мудростью, а земля в 15 футах вокруг тебя становится труднопроходимой для врагов.', author_description='Один режим превращает тебя в хищника, другой — в ходячий кусок древнего леса. Выбираешь, что сегодня нужнее: давление или стойкость.', author_comment='Природа выдаёт два профиля настроек. Оба довольно недружелюбны.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Аспект выбирается при сотворении и не меняется до окончания заклинания. Требуется концентрация.', casting_time='1 бонусное действие' where slug='guardian-of-nature' and source_kind='official';

update public.spell_catalog set name_ru='Психическое копьё Раулотима', effect_summary='Цель в пределах 120 футов делает спасбросок Интеллекта. При провале получает 7к6 психического урона и становится Недееспособной до начала твоего следующего хода; при успехе получает половину урона. Вместо видимой цели можно произнести настоящее имя существа: если оно в пределах дистанции, копьё найдёт его даже без линии зрения.', author_description='Ментальный удар, которому иногда достаточно знать имя адресата. Очень неприятная комбинация урона и потери действий.', author_comment='Когда заклинание спрашивает настоящее имя, обычно разговор уже пошёл не туда.', upcast='Урон увеличивается на 1к6 за каждый уровень ячейки выше 4.', notes='Если названного существа нет в пределах дистанции, заклинание рассеивается без эффекта.', casting_time='1 действие' where slug='raulothim-s-psychic-lance' and source_kind='official';

update public.spell_catalog set name_ru='Тень Мойла', effect_summary='На срок до 1 минуты с концентрацией тебя окутывают огненные тени. Для других существ ты сильно заслонён. Тени превращают яркий свет в пределах 10 футов в тусклый, а тусклый — во тьму. Ты получаешь сопротивление урону излучением; когда существо в пределах 10 футов попадает по тебе атакой, оно получает 2к8 некротического урона.', author_description='Ты становишься ходячим пятном злой тьмы, которое хуже видно, труднее убить светом и неприятно бить в рукопашной.', author_comment='Если тень начала отвечать некротическим уроном, пора перестать её трогать.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется материальный компонент — глаз нежити в драгоценном камне стоимостью не менее 150 зм. Он не расходуется.', casting_time='1 действие' where slug='shadow-of-moil' and source_kind='official';

update public.spell_catalog set name_ru='Болезненное сияние', effect_summary='Создаёшь сферу тусклого зеленоватого света радиусом 30 футов на срок до 10 минут с концентрацией. Существо, впервые за ход входящее в область или начинающее там ход, делает спасбросок Телосложения. При провале получает 4к10 урона излучением, получает 1 уровень Истощения и начинает излучать тусклый свет в радиусе 5 футов, из-за чего не может пользоваться преимуществами невидимости. Истощение от заклинания исчезает, когда оно заканчивается.', author_description='Это не вспышка, а медленная зона распада: чем дольше враг внутри, тем хуже становится его состояние.', author_comment='Редкая магия, где фраза «просто постой там ещё раунд» звучит как угроза.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Существо делает спасбросок не более одного раза за ход; уровни Истощения от этого заклинания складываются.', casting_time='1 действие' where slug='sickening-radiance' and source_kind='official';

update public.spell_catalog set name_ru='Буря заклинательного огня', effect_summary='Создаёшь цилиндр заклинательного огня радиусом 20 футов и высотой 20 футов на срок до 1 минуты с концентрацией. Существо в области при появлении, первом входе за ход или окончании хода там делает спасбросок Телосложения: при провале получает 4к10 урона излучением, при успехе — половину. Кроме того, существо, пытающееся сотворить заклинание внутри цилиндра, делает спасбросок Телосложения; при провале заклинание рассеивается без эффекта и действие тратится, но ячейка не расходуется.', author_description='Светящийся столб одновременно жарит врагов и превращает зону в крайне плохое место для чужой магии.', author_comment='Антимагия обычно тихая. Эта решила ещё и светиться на весь бой.', upcast='Урон увеличивается на 1к10 за каждый уровень ячейки выше 4.', notes='При сотворении можно назначить существ, которых эффект не затрагивает. У заклинания есть отдельный вариант кругового сотворения с увеличенными масштабом и длительностью.', casting_time='1 действие' where slug='spellfire-storm' and source_kind='official';

update public.spell_catalog set name_ru='Дух смерти', effect_summary='Призываешь дух, воплощающий смерть, в свободное пространство в пределах 60 футов на срок до 1 часа с концентрацией. Он использует статблок Духа-жнеца, действует сразу после тебя на твоей инициативе и выполняет твои устные команды; без команды Уклоняется и старается избегать опасности.', author_description='Это уже не скелет и не зомби, а персонифицированная смерть на временном контракте.', author_comment='Когда у призыва есть коса и отдельный статблок, спорить о должностных обязанностях обычно не приходится.', upcast='Ячейкой 5 уровня или выше используй её уровень везде, где уровень заклинания указан в статблоке духа.', notes='Требуется концентрация. Материальный фокус — позолоченная карта с изображением аватара смерти стоимостью 400+ зм; он не расходуется.', casting_time='1 действие' where slug='spirit-of-death' and source_kind='official';

update public.spell_catalog set name_ru='Штормовая сфера', effect_summary='Создаёшь сферу вихря радиусом 20 футов на срок до 1 минуты с концентрацией. При появлении и когда существо заканчивает ход внутри, оно делает спасбросок Силы; при провале получает 2к6 дробящего урона. Пространство сферы — труднопроходимая местность. Бонусным действием каждый ход можешь метнуть молнию в существо внутри сферы или в пределах 60 футов от её центра: дальнобойная атака заклинанием наносит 4к6 электрического урона, с преимуществом по цели внутри сферы.', author_description='Одно заклинание создаёт и постоянную зону урагана, и личную грозовую батарею для бонусных действий.', author_comment='Сначала ветер портит позицию, потом молния портит настроение.', upcast='И дробящий урон вихря, и урон молнии увеличиваются на 1к6 за каждый уровень ячейки выше 4.', notes='Требуется концентрация. Дальнобойная атака молнией выполняется бонусным действием.', casting_time='1 действие' where slug='storm-sphere' and source_kind='official';

update public.spell_catalog set name_ru='Призыв аберрации', effect_summary='Призываешь дух аберрации в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь форму — созерцатель, слаад или звёздное порождение; форма меняет особые способности духа. Он действует сразу после тебя и выполняет твои команды.', author_description='Три разных вида космической неправильности на выбор: летающий глаз, регенерирующий слаад или нечто из далёкой тьмы.', author_comment='Если нормальные союзники закончились, всегда остаётся дальний космос.', upcast='При использовании ячейки выше 4 её уровень используется в характеристиках духа, повышая его хиты, атаки и другие параметры статблока.', notes='Требуется концентрация. Материальный фокус стоимостью 400+ зм не расходуется; форма выбирается при сотворении.', casting_time='1 действие' where slug='summon-aberration' and source_kind='official';

update public.spell_catalog set name_ru='Призыв конструкта', effect_summary='Призываешь дух конструкта в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь материал — глина, металл или камень — и соответствующий набор свойств. Дух действует сразу после тебя и подчиняется командам.', author_description='Магический напарник, которого можно заказать в трёх материалах под разные боевые задачи.', author_comment='Гарантия не распространяется на сознательное отправление конструкта под огненный шар.', upcast='При использовании ячейки выше 4 её уровень используется в характеристиках духа, усиливая статблок.', notes='Требуется концентрация. Материальный фокус стоимостью 400+ зм не расходуется. Тип конструкта выбирается при сотворении.', casting_time='1 действие' where slug='summon-construct' and source_kind='official';

update public.spell_catalog set name_ru='Призыв элементаля', effect_summary='Призываешь элементального духа в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь стихию — воздух, землю, огонь или воду; выбранная форма определяет сопротивления, скорость и особые свойства духа. Он действует сразу после тебя и выполняет команды.', author_description='Карманная стихия под конкретную задачу: летать, гореть, терпеть удары или плавать.', author_comment='Погода по вызову, только у погоды есть атаки и инициатива.', upcast='При использовании ячейки выше 4 её уровень используется в характеристиках духа, усиливая его статблок.', notes='Требуется концентрация. Материальный фокус стоимостью 400+ зм не расходуется. Стихия выбирается при сотворении.', casting_time='1 действие' where slug='summon-elemental' and source_kind='official';

update public.spell_catalog set name_ru='Призыв высшего демона', effect_summary='Призываешь одного демона с ПО 5 или ниже в свободное пространство в пределах 60 футов на срок до 1 часа с концентрацией. В начале он выполняет твои словесные команды, но в конце каждого своего хода делает спасбросок Харизмы; при успехе освобождается от контроля и действует по собственной воле, обычно атакуя ближайших существ.', author_description='В отличие от малых демонов, здесь ты вызываешь одну большую проблему и какое-то время убеждаешь её быть чужой проблемой.', author_comment='Контракт короткий, юрист — Харизма демона.', upcast='Максимальный ПО демона увеличивается на 1 за каждый уровень ячейки выше 4.', notes='Истинное имя демона мешает ему сопротивляться контролю. Кровь гуманоида можно использовать для защитного круга, который призванный демон не способен пересечь.', casting_time='1 действие' where slug='summon-greater-demon' and source_kind='official';

update public.spell_catalog set name_ru='Водяная сфера', effect_summary='Создаёшь парящую сферу воды радиусом 5 футов на срок до 1 минуты с концентрацией. Большое или меньшее существо, оказавшееся в её пространстве, делает спасбросок Силы; при провале становится Опутанным внутри воды. Действием сферу можно перемещать до 30 футов, захватывая новых существ; удерживаемые цели двигаются вместе с ней.', author_description='Мобильная водяная тюрьма: поймал, поднял, увёз туда, где пленнику совсем не нравится.', author_comment='Аквариум, в котором рыбой становится тот, кто провалил Силу.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. В сфере помещается до четырёх Средних или меньших существ либо одно Большое. Опутанная цель может повторять спасбросок в конце своих ходов.', casting_time='1 действие' where slug='watery-sphere' and source_kind='official';

commit;